from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        extra="ignore",
    )

    groq_api_key: str = ""
    groq_model: str = "llama-3.3-70b-versatile"

    adzuna_app_id: str = ""
    adzuna_app_key: str = ""
    adzuna_country: str = "gb"

    @property
    def has_groq(self) -> bool:
        return bool(self.groq_api_key.strip())

    @property
    def has_adzuna(self) -> bool:
        return bool(self.adzuna_app_id.strip() and self.adzuna_app_key.strip())


settings = Settings()

from pathlib import Path


def load_resume_text(path: str | Path) -> str:
    """Load plain text from PDF, DOCX, or TXT resume files."""
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(f"Resume not found: {path}")

    suffix = path.suffix.lower()
    if suffix == ".txt":
        return path.read_text(encoding="utf-8", errors="replace").strip()

    if suffix == ".pdf":
        from pypdf import PdfReader

        reader = PdfReader(str(path))
        pages = [page.extract_text() or "" for page in reader.pages]
        text = "\n".join(pages).strip()
        if not text:
            raise ValueError("PDF contained no extractable text.")
        return text

    if suffix in {".docx", ".doc"}:
        from docx import Document

        doc = Document(str(path))
        paragraphs = [p.text for p in doc.paragraphs if p.text.strip()]
        text = "\n".join(paragraphs).strip()
        if not text:
            raise ValueError("DOCX contained no text.")
        return text

    raise ValueError(f"Unsupported format: {suffix}. Use .pdf, .docx, or .txt")

import httpx

from src.config import settings

REMOTIVE_URL = "https://remotive.com/api/remote-jobs"


def _search_remotive(query: str, limit: int = 10) -> list[dict]:
    """Free job API — no API key required."""
    params = {}
    if query.strip():
        params["search"] = query.strip()

    with httpx.Client(timeout=30.0) as client:
        resp = client.get(REMOTIVE_URL, params=params)
        resp.raise_for_status()
        jobs = resp.json().get("jobs", [])

    results = []
    for job in jobs[:limit]:
        results.append(
            {
                "title": job.get("title", ""),
                "company": job.get("company_name", ""),
                "location": job.get("candidate_required_location", "Remote"),
                "description": (job.get("description") or "")[:2000],
                "url": job.get("url", ""),
                "source": "remotive",
                "tags": job.get("tags", []),
            }
        )
    return results


def _search_adzuna(query: str, location: str = "", limit: int = 10) -> list[dict]:
    """Adzuna free tier — requires app id/key from developer.adzuna.com."""
    country = settings.adzuna_country
    url = f"https://api.adzuna.com/v1/api/jobs/{country}/search/1"
    params = {
        "app_id": settings.adzuna_app_id,
        "app_key": settings.adzuna_app_key,
        "results_per_page": min(limit, 20),
        "what": query,
    }
    if location.strip():
        params["where"] = location.strip()

    with httpx.Client(timeout=30.0) as client:
        resp = client.get(url, params=params)
        resp.raise_for_status()
        data = resp.json()

    results = []
    for job in data.get("results", [])[:limit]:
        results.append(
            {
                "title": job.get("title", ""),
                "company": job.get("company", {}).get("display_name", ""),
                "location": job.get("location", {}).get("display_name", ""),
                "description": (job.get("description") or "")[:2000],
                "url": job.get("redirect_url", ""),
                "source": "adzuna",
                "tags": [],
            }
        )
    return results


def search_jobs(
    query: str,
    location: str = "",
    limit: int = 10,
    prefer_adzuna: bool = True,
) -> list[dict]:
    """
    Search jobs using free APIs.
    Tries Adzuna when keys are set; always merges Remotive remote listings.
    """
    all_jobs: list[dict] = []
    seen_urls: set[str] = set()

    def add_batch(batch: list[dict]) -> None:
        for job in batch:
            url = job.get("url", "")
            if url and url in seen_urls:
                continue
            if url:
                seen_urls.add(url)
            all_jobs.append(job)

    if prefer_adzuna and settings.has_adzuna:
        try:
            add_batch(_search_adzuna(query, location, limit=limit))
        except httpx.HTTPError:
            pass

    try:
        add_batch(_search_remotive(query, limit=limit))
    except httpx.HTTPError:
        pass

    return all_jobs[:limit]

import re
from typing import Any


def _normalize_tokens(text: str) -> set[str]:
    tokens = re.findall(r"[a-z0-9+#.]+", text.lower())
    return {t for t in tokens if len(t) > 2}


def match_resume_to_jobs(
    resume_skills: list[str],
    jobs: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Score each job by overlap between resume skills and job description."""
    skill_set = _normalize_tokens(" ".join(resume_skills))

    scored: list[dict[str, Any]] = []
    for job in jobs:
        blob = " ".join(
            [
                job.get("title", ""),
                job.get("description", ""),
                " ".join(job.get("tags", [])),
            ]
        )
        job_tokens = _normalize_tokens(blob)
        if not skill_set:
            overlap = set()
            score = 0.0
        else:
            overlap = skill_set & job_tokens
            score = round(len(overlap) / max(len(skill_set), 1) * 100, 1)

        missing = sorted(skill_set - job_tokens)[:15]
        matched = sorted(overlap)

        scored.append(
            {
                **job,
                "match_score": score,
                "matched_skills": matched,
                "missing_for_job": missing,
            }
        )

    scored.sort(key=lambda j: j["match_score"], reverse=True)
    return scored

